import quantile = require( './index' );


// TESTS //

{
	quantile( 0.2, 0.0, 1 ); // $ExpectType number
	quantile( 0.1, 2.0, 4 ); // $ExpectType number
	quantile( NaN, 0.0, 1 ); // $ExpectType number
}

{
	quantile( true, 0.0, 1 ); // $ExpectError
	quantile( false, 0.0, 1 ); // $ExpectError
	quantile( '5', 0.0, 1 ); // $ExpectError
	quantile( [], 0.0, 1 ); // $ExpectError
	quantile( {}, 0.0, 1 ); // $ExpectError
	quantile( ( x: number ): number => x, 0.0, 1 ); // $ExpectError

	quantile( 0.9, true, 1 ); // $ExpectError
	quantile( 0.5, '5', 1 ); // $ExpectError
	quantile( 0.8, [], 1 ); // $ExpectError
	quantile( 0.9, {}, 1 ); // $ExpectError
	quantile( 0.8, ( x: number ): number => x, 1 ); // $ExpectError

	quantile( 0.9, 0.0, true ); // $ExpectError
	quantile( 0.5, 0.0, '5' ); // $ExpectError
	quantile( 0.8, 0.0, [] ); // $ExpectError
	quantile( 0.9, 0.0, {} ); // $ExpectError
	quantile( 0.8, 0.0, ( x: number ): number => x ); // $ExpectError
}

{
	quantile(); // $ExpectError
	quantile( 0.2 ); // $ExpectError
	quantile( 0.2, 0.0 ); // $ExpectError
	quantile( 0.2, 0.0, 1, 4 ); // $ExpectError
}

{
	quantile.factory( 0.0, 1 ); // $ExpectType Unary
}

{
	const fcn = quantile.factory( 0.0, 1 );
	fcn( 0.2 ); // $ExpectType number
}

{
	const fcn = quantile.factory( 0.0, 1 );
	fcn( true ); // $ExpectError
	fcn( false ); // $ExpectError
	fcn( '5' ); // $ExpectError
	fcn( [] ); // $ExpectError
	fcn( {} ); // $ExpectError
	fcn( ( x: number ): number => x ); // $ExpectError
}

{
	const fcn = quantile.factory( 0.0, 1 );
	fcn(); // $ExpectError
	fcn( 0.2, 0 ); // $ExpectError
	fcn( 0.2, 0, 1 ); // $ExpectError
}

{
	quantile.factory( true, 1 ); // $ExpectError
	quantile.factory( false, 1 ); // $ExpectError
	quantile.factory( '5', 1 ); // $ExpectError
	quantile.factory( [], 1 ); // $ExpectError
	quantile.factory( {}, 1 ); // $ExpectError
	quantile.factory( ( x: number ): number => x, 1 ); // $ExpectError

	quantile.factory( 0.0, true ); // $ExpectError
	quantile.factory( 0.0, false ); // $ExpectError
	quantile.factory( 0.0, '5' ); // $ExpectError
	quantile.factory( 0.0, [] ); // $ExpectError
	quantile.factory( 0.0, {} ); // $ExpectError
	quantile.factory( 0.0, ( x: number ): number => x ); // $ExpectError
}

{
	quantile.factory(); // $ExpectError
	quantile.factory( 2 ); // $ExpectError
	quantile.factory( 2, 2, 3 ); // $ExpectError
}
